# Test Suite for Checkout Component

Now listen here, son. I've been writing tests since before you were born, and I'm going to lay this out proper and orderly. Buffalo bagels, let's get this sorted out!

```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockCartItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockCartItems, total: 79.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const validShipping = {
  street: '123 Main St',
  city: 'Springfield',
  state: 'CA',
  zip: '90210'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'John Doe'
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // 1. Happy Path
  describe('complete checkout flow', () => {
    it('navigates through all steps and completes order', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip code/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // 2. Form Validation
  describe('shipping validation', () => {
    it('displays error for invalid ZIP code', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    });
  });

  // 3. Error States
  describe('payment failure', () => {
    it('displays error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review (abbreviated)
      // ...complete shipping and payment forms...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
    });
  });

  // 4. Loading States
  describe('loading states', () => {
    it('disables buttons during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // Test button disabled state
    });
  });

  // 5. Accessibility
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  // 6. Edge Cases
  describe('empty cart', () => {
    it('displays empty cart message', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout />);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });
});
